    fn from_allow_unit_transport_query(
        value: &sys::AllowUnitTransportQuery,
    ) -> Result<AllowUnitTransportQuery> {
        Ok(AllowUnitTransportQuery {
            transporter_id: (value.transporterID) as _,
            transporter_def_id: (value.transporterDefID) as _,
            transporter_team: (value.transporterTeam) as _,
            transportee_id: (value.transporteeID) as _,
            transportee_def_id: (value.transporteeDefID) as _,
            transportee_team: (value.transporteeTeam) as _,
        })
    }
    fn from_float3(value: &sys::Float3) -> Result<Float3> {
        Ok(Float3 {
            x: (value.x) as _,
            y: (value.y) as _,
            z: (value.z) as _,
        })
    }
    fn from_game_setup_player_state(
        value: &sys::GameSetupPlayerState,
    ) -> Result<GameSetupPlayerState> {
        Ok(GameSetupPlayerState {
            player_id: (value.playerID) as _,
            state: unsafe { read_string(value.state, None)? },
        })
    }
    fn from_key_action(value: &sys::KeyAction) -> Result<KeyAction> {
        Ok(KeyAction {
            command: unsafe { read_string(value.command, None)? },
            extra: unsafe { read_string(value.extra, None)? },
            bound_with: unsafe { read_string(value.boundWith, None)? },
        })
    }
    fn from_native_callin_command(
        value: &sys::NativeCallinCommand,
    ) -> Result<NativeCallinCommand> {
        Ok(NativeCallinCommand {
            id: (value.id) as _,
            time_out: (value.timeOut) as _,
            page_index: (value.pageIndex) as _,
            num_params: (value.numParams) as _,
            tag: (value.tag) as _,
            options: (value.options) as _,
            params: unsafe { read_slice(value.params, value.numParams as usize)? }
                .iter()
                .map(|item| -> Result<_> { Ok((*item) as _) })
                .collect::<Result<Vec<_>>>()?,
        })
    }
    fn from_resource_excess_entry(
        value: &sys::ResourceExcessEntry,
    ) -> Result<ResourceExcessEntry> {
        Ok(ResourceExcessEntry {
            team_id: (value.teamID) as _,
            resources: (value.resources)
                .iter()
                .map(|item| -> Result<_> { Ok((*item) as _) })
                .collect::<Result<Vec<_>>>()?,
        })
    }
